examples.code:
$saw($chord('C3[m9]')).$.lpf('c5').$.comp({
  sidechain: $perc($clock.beatTrigger, { decay: 0.2 }),
  threshold: 1, ratio: 8, attack: 0.005, release: 0.2,
}).out()

const bands = $xover($saw('c2'), { lowMidFreq: '200hz', midHighFreq: '2000hz' })
$mix([
  $comp(bands.low, { threshold: 2.5, ratio: 4 }),
  $comp(bands.mid, { threshold: 3, ratio: 3 }),
  $comp(bands.high, { threshold: 2, ratio: 6 }),
]).out()

const grains = $pulse('8hz')
$granular($saw('a3'), grains, {
  time: $sah($noise('white').range(0, 2), grains),
  freq: $cycle($p('[c4, e4, g4] [b3, d4, g4]')),
  rootFreq: 'a3',
  width: 4,
  spread: 2,
  mix: 4,
}).out()

const grains = $pulse('8hz')
$granularSampler($wavs().pad, grains, {
  time: $sah($noise('white').range(0, 5), grains),
  width: 4,
  spread: 2,
}).out()

const grains = $pulse('8hz')
const cloud = $granular($saw('a3'), grains, { mix: 4, quality: 'dirtyTape' })
$reverb($wowFlutter(cloud), 3, { size: 5, tone: 2 }).out()

const seq = $cycle($p('c3 eb3 g3 bb3'))
const env = $perc(seq.trig, { decay: 0.5 })
$wavetable(seq, $wavs().tables.pad, env.range(0, 4)).amp(env).out()

$saw('c2').$.eq({
  sections: [
    { type: 'lowShelf', freq: '150hz', gain: 3 },
    { type: 'peak', freq: $sine('0.5hz').range('400hz', '2000hz'), gain: -6, q: 2 },
    { type: 'highpass', freq: '40hz' },
  ],
  adaptiveQ: true,
}).out()

$saw(['c2', 'g2']).$.eq({
  sections: [
    [{ type: 'highShelf', freq: '3000hz', gain: -6 }],
    [{ type: 'highShelf', freq: '3000hz', gain: 4 }],
  ],
}).out()

const voice = $saw($cycle($p('c3 eb3 g3 ~'))).amp($perc($clock.beatTrigger, { decay: 0.15 }))
voice.out()
$delayRead($buffer(voice, 1), 0.375).amp(2.5).out()

const voice = $saw($cycle($p('c3 eb3 g3 ~'))).amp($perc($clock.beatTrigger, { decay: 0.15 }))
voice.out()
const echoes = $buffer(voice, 1)
$delayRead(echoes, 0.375).amp(2.5).out()
$delayRead(echoes, 0.75).amp(1.25).out()

$setGroove($swing(0.6))
const hats = $cycle($p('c5*8'))
const bass = $cycle($p('c2*4'), { groove: 0 })
$noise('white').amp($perc(hats.trig, { decay: 0.05 })).amp(hats.velocity).out()
$saw(bass).$.lpf('c4', 1).amp($adsr(bass.gate)).out()

argument_spans.description:
Per-source editor argument spans. Consumed entirely TS-side (merged
into the params' `__argument_spans` before IPC) and never read here;
optional on the wire so a hand-built payload may omit it.

examples.code:
const g = $groove({ timing: [0, 0.3], velocity: [1, 0.6], grid: 8 })
const seq = $cycle($p('c4 e4 g4 c5 g4 e4 c4 g3'), { groove: g, velocity: g.velocity })
$sine(seq).amp($adsr(seq.gate)).amp(seq.velocity).out()

const seq = $cycle($p('c3 eb3 g3 bb2'))
const env = $perc(seq.trig, { decay: 0.4 })
$sine(seq).$.unstable.shape.fold('westcoast', env.range(-2, 4)).amp(env).out()
